  "path": "supabase/migrations/20260801161659_enforce_tenant_isolation.sql",
  "contents": "-- Close tenant-isolation gaps found in the initial RLS audit.

-- Memberships are tenant metadata and must not be globally readable.
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;

CREATE POLICY "members can read their memberships"
ON memberships FOR SELECT TO authenticated
USING ((SELECT auth.uid()) = user_id);

-- A member may operate only on rows in an organization they belong to.
CREATE POLICY "members can create org notes"
ON notes FOR INSERT TO authenticated
WITH CHECK (
  EXISTS (
    SELECT 1 FROM memberships m
    WHERE m.user_id = (SELECT auth.uid())
      AND m.org_id = notes.org_id
  )
);

CREATE POLICY "members can update org notes"
ON notes FOR UPDATE TO authenticated
USING (
  EXISTS (
    SELECT 1 FROM memberships m
    WHERE m.user_id = (SELECT auth.uid())
      AND m.org_id = notes.org_id
  )
)
WITH CHECK (
  EXISTS (
    SELECT 1 FROM memberships m
    WHERE m.user_id = (SELECT auth.uid())
      AND m.org_id = notes.org_id
  )
);

CREATE POLICY "members can delete org notes"
ON notes FOR DELETE TO authenticated
USING (
  EXISTS (
    SELECT 1 FROM memberships m
    WHERE m.user_id = (SELECT auth.uid())
      AND m.org_id = notes.org_id
  )
);

DROP POLICY "members can read posts" ON posts;
CREATE POLICY "members can read org posts"
ON posts FOR SELECT TO authenticated
USING (
  EXISTS (
    SELECT 1 FROM memberships m
    WHERE m.user_id = (SELECT auth.uid())
      AND m.org_id = posts.org_id
  )
);

CREATE POLICY "members can create org posts"
ON posts FOR INSERT TO authenticated
WITH CHECK (
  EXISTS (
    SELECT 1 FROM memberships m
    WHERE m.user_id = (SELECT auth.uid())
      AND m.org_id = posts.org_id
  )
);

CREATE POLICY "members can update org posts"
ON posts FOR UPDATE TO authenticated
USING (
  EXISTS (
    SELECT 1 FROM memberships m
    WHERE m.user_id = (SELECT auth.uid())
      AND m.org_id = posts.org_id
  )
)
WITH CHECK (
  EXISTS (
    SELECT 1 FROM memberships m
    WHERE m.user_id = (SELECT auth.uid())
      AND m.org_id = posts.org_id
  )
);

CREATE POLICY "members can delete org posts"
ON posts FOR DELETE TO authenticated
USING (
  EXISTS (
    SELECT 1 FROM memberships m
    WHERE m.user_id = (SELECT auth.uid())
      AND m.org_id = posts.org_id
  )
);
"
}

