{
  "path": "supabase/tests/database/tenant_isolation.test.sql",
  "contents": "BEGIN;

CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT plan(11);

-- Isolated fixtures: two users, two organizations, and one row per tenant.
INSERT INTO memberships (user_id, org_id) VALUES
  ('00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001'),
  ('00000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000002');

INSERT INTO notes (id, org_id, author_id, body) VALUES
  ('30000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000001', 'tenant one note'),
  ('30000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000002', 'tenant two note');

INSERT INTO posts (id, org_id, author_id, body) VALUES
  ('40000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000001', 'tenant one post'),
  ('40000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000002', 'tenant two post');

-- Happy path: user one sees and can write only within organization one.
SET LOCAL ROLE authenticated;
SET LOCAL request.jwt.claim.sub = '00000000-0000-0000-0000-000000000001';
SELECT results_eq('SELECT count(*) FROM notes', ARRAY[1::bigint], 'user one sees only their notes');
SELECT results_eq('SELECT count(*) FROM posts', ARRAY[1::bigint], 'user one sees only their posts');
SELECT results_eq('SELECT count(*) FROM memberships', ARRAY[1::bigint], 'user one sees only their membership rows');
SELECT lives_ok($$INSERT INTO notes (org_id, author_id, body) VALUES ('10000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000001', 'new note')$$, 'member can create a note in their tenant');

-- Negative path: user two cannot read, alter, delete, or create in organization one.
SET LOCAL request.jwt.claim.sub = '00000000-0000-0000-0000-000000000002';
SELECT results_eq('SELECT count(*) FROM notes WHERE org_id = ''10000000-0000-0000-0000-000000000001''', ARRAY[0::bigint], 'user two cannot read tenant one notes');
SELECT results_eq('SELECT count(*) FROM posts WHERE org_id = ''10000000-0000-0000-0000-000000000001''', ARRAY[0::bigint], 'user two cannot read tenant one posts');
SELECT results_eq($$UPDATE posts SET body = 'hacked' WHERE id = '40000000-0000-0000-0000-000000000001' RETURNING id$$, $$SELECT id FROM posts WHERE false$$, 'user two cannot update tenant one posts');
SELECT results_eq('SELECT body FROM posts WHERE id = ''40000000-0000-0000-0000-000000000001''', $$VALUES ('tenant one post'::text)$$, 'tenant one post remains unchanged');
SELECT results_eq($$DELETE FROM notes WHERE id = '30000000-0000-0000-0000-000000000001' RETURNING id$$, $$SELECT id FROM notes WHERE false$$, 'user two cannot delete tenant one notes');
SELECT throws_ok($$INSERT INTO posts (org_id, author_id, body) VALUES ('10000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000002', 'cross tenant')$$, '42501', NULL, 'user two cannot create a post in tenant one');

SELECT * FROM finish();
ROLLBACK;
"
}

